/**
 * Shader of the line waves.
 *
 * ## The mathematical idea
 *
 * The frame is cut into horizontal bands, one line per band. Each line is a
 * y = f(x): the sum of two non-harmonic sines, phase-shifted by the index of
 * the band. The phase offset is what makes the figure: at a given instant, the
 * crests of neighbouring lines are not aligned, and the eye reads a diagonal
 * sheet sliding past while each line only ever moves up and down.
 *
 * The fragment knows only its own band and its two neighbours: the amplitude is
 * expressed in band heights and clamped to one, so a line never strays further
 * than one band from its axis. Three evaluations per fragment, whatever the
 * number of lines.
 *
 * The distance to the line is divided by the norm of its slope: without that,
 * the stroke thickens where it is flat and thins where it climbs.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the ink of the lines.
 * - `uColorC` — the glint of the crests.
 * - `uCount` — number of lines.
 * - `uAmplitude` — height of the swell, in band heights.
 * - `uSpeed` — speed of the swell.
 * - `uThickness` — thickness of the stroke, as a fraction of the height.
 */
export const LINE_WAVES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uCount;
uniform float uAmplitude;
uniform float uSpeed;
uniform float uThickness;

// Two non-harmonic sines: the 4/9 ratio never falls back into phase within the
// frame, so the swell does not repeat to the eye.
float swell(float x, float t, float phase) {
  return sin(x * 4.0 - t + phase) * 0.7 + sin(x * 9.0 + t * 0.6 - phase * 1.7) * 0.3;
}

// Derivative of the swell with respect to x, to normalise the thickness.
float slopeOf(float x, float t, float phase) {
  return cos(x * 4.0 - t + phase) * 2.8 + cos(x * 9.0 + t * 0.6 - phase * 1.7) * 2.7;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float x = vUv.x * aspect;
  float t = uTime * uSpeed;

  float count = clamp(uCount, 2.0, 48.0);
  float pitch = 1.0 / count;
  float amplitude = clamp(uAmplitude, 0.0, 1.0) * pitch;

  float px = 1.0 / max(uResolution.y, 1.0);
  float thickness = max(uThickness, px);

  float band = floor(vUv.y * count);
  float ink = 0.0;
  float crest = 0.0;

  // The fragment's band and its two neighbours: the amplitude is clamped to one
  // band height, a line never goes further than that.
  for (int k = -1; k <= 1; k += 1) {
    float i = band + float(k);
    if (i < 0.0 || i >= count) continue;

    float phase = i * 0.55;
    float wave = swell(x, t, phase);
    float centre = (i + 0.5) * pitch + wave * amplitude;

    // The slope is in frame units: the amplitude enters it, and so does the aspect.
    float slope = slopeOf(x, t, phase) * amplitude * aspect;
    float d = abs(vUv.y - centre) / sqrt(1.0 + slope * slope);

    float line = 1.0 - smoothstep(thickness - px, thickness + px, d);
    ink = max(ink, line);
    // The crest: where the swell is at its highest, the stroke lights up.
    crest = max(crest, line * smoothstep(0.3, 1.0, wave));
  }

  vec3 colour = mix(uColorA, uColorB, ink * 0.85);
  colour = mix(colour, uColorC, crest * 0.9);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Line waves: thin horizontal lines rippling with an offset phase.
 *
 * ## The principle
 *
 * One line per horizontal band, each displaced by the same swell with a phase
 * offset of its own rank. No line is ever stroked: the fragment measures its
 * distance to the curve of its own band and of its two neighbours.
 *
 * What sets this entry apart from its cousins: the stroke is thin, the rhythm
 * is slow, and the motion is horizontal — the swell runs from left to right,
 * and the phase offset between lines draws a diagonal sheet.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its
 * fallback. Reading the tokens, converting them to floats and re-reading them
 * when the theme changes all come from the engine — copying that here would
 * leave as many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { LINE_WAVES_FRAGMENT } from './line-waves.shader.js'

/** What the escape hatch receives. */
export interface LineWavesControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface LineWavesOwnProps {
  /** Number of lines. Clamped to forty-eight by the shader. @defaultValue 24 */
  count?: number
  /** Height of the swell, in band heights. @defaultValue 0.6 */
  amplitude?: number
  /** Speed of the swell. @defaultValue 0.4 */
  speed?: number
  /** Thickness of the stroke, as a fraction of the height. @defaultValue 0.0025 */
  thickness?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<LineWavesControls>
}

/** All props. */
export type LineWavesProps = Customisable<LineWavesOwnProps>

/** Tokens used by default: the background, the ink, the glint of the crests. */
const DEFAULT_TOKENS = ['--o-theme-bg', '--o-theme-fg', '--o-palette-brand-500'] as const

/** Default fallback: a frozen tint, in the same tones. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Number of lines at low quality.
 *
 * The per-fragment cost does not depend on the number of lines — three bands
 * are evaluated whatever happens. What costs is aliasing: tightly packed lines
 * at a reduced pixel density shimmer. Fewer lines, more space between them, and
 * the stroke stays crisp.
 */
const LOW_COUNT = 12

/**
 * Line waves.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <LineWaves className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function LineWaves({
  count = 24,
  amplitude = 0.6,
  speed = 0.4,
  thickness = 0.0025,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: LineWavesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: LINE_WAVES_FRAGMENT,
    colors,
    uniforms: {
      uCount: count,
      uAmplitude: amplitude,
      uSpeed: speed,
      uThickness: thickness,
    },
    name: 'line-waves',
    degrade: (quality) => ({
      uCount: quality === 'low' ? Math.min(count, LOW_COUNT) : count,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
